 useEffect(()=>{const fn=e=>change(d=>{const i=d.items.find(x=>x.id===e.detail.id);if(i){i.x=e.detail.x;i.z=e.detail.z;if(i.mount==='wall'){if(Number.isFinite(e.detail.mountHeight))i.mountHeight=e.detail.mountHeight;wallPlacement(i,d.room)}else keepFurnitureInRoom(i,d.room)}});window.addEventListener('roomify-drag',fn);return()=>window.removeEventListener('roomify-drag',fn)},[]);
